mapper.select:
SELECT a.*, u.real_name AS student_name, u.class_name
FROM leave_application a
JOIN `user` u ON a.student_id = u.id
WHERE a.student_id = #{studentId}
ORDER BY a.create_time DESC
LIMIT #{offset}, #{limit}

SELECT DISTINCT a.*, u.real_name AS student_name, u.class_name
FROM leave_application a
JOIN `user` u ON a.student_id = u.id
WHERE a.status = #{status}
AND u.counselor_id = #{approverId}
ORDER BY a.create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT a.id)
FROM leave_application a
JOIN `user` u ON a.student_id = u.id
WHERE a.status = #{status}
AND u.counselor_id = #{approverId}

SELECT COUNT(DISTINCT a.id)
FROM leave_application a
JOIN `user` u ON a.student_id = u.id
WHERE a.status = #{status}
AND u.counselor_id = #{approverId}

SELECT a.*, u.real_name AS student_name, u.class_name FROM leave_application a JOIN `user` u ON a.student_id = u.id WHERE a.status IN ('APPROVED', 'CANCELLING', 'CANCELLED')
AND u.department = #{department}
AND u.class_name = #{className}
ORDER BY a.create_time DESC
